b<-'.';out<-file.path(b,'全元素谱复核_20261118');txt<-paste(readLines(file.path(out,'code/02_full_spectrum.R'),warn=FALSE),collapse='\n');eval(parse(text=strsplit(txt,'all<-list();counter<-0;started<-Sys.time()',fixed=TRUE)[[1]][1]));res<-read.csv(file.path(out,'output/05_full_spectrum_primary_6392.csv'));check<-list()
# Verify every interpretable coefficient through weighted QR normal equations, independently of svyglm.
for(i in 1:nrow(reg)){rr<-reg[i,];xxall<-getx(rr)$x;cv<-cvfor(rr);de<-caldes[[rr$weight]];ii<-de$variables$.rowid;ww<-as.numeric(weights(de));xx<-xxall[ii];ids<-which(res$variable==rr$variable&res$status=='ok')
 for(j in ids){yy<-if(res$layer[j]=='individual')ifelse(a[[res$metabolite[j]]][ii]>0,log2(a[[res$metabolite[j]]][ii]),NA)else a[[res$metabolite[j]]][ii];m<-a$age[ii]>=20&!is.na(a$group[ii])&is.finite(a[[rr$weight]][ii])&a[[rr$weight]][ii]>0&is.finite(xx)&is.finite(yy)&complete.cases(de$variables[,cv]);m[is.na(m)]<-FALSE;dd<-de$variables[m,];dd$xx<-xx[m];dd$zz<-(yy[m]-mean(yy[m]))/sd(yy[m]);X<-model.matrix(as.formula(paste('~xx+',paste(cv,collapse='+'))),dd);fit<-qr.solve(X*sqrt(ww[m]),dd$zz*sqrt(ww[m]),tol=1e-9);delta<-unname(fit['xx'])-res$beta[j];check[[length(check)+1]]<-data.frame(variable=rr$variable,metabolite=res$metabolite[j],beta_survey=res$beta[j],beta_QR=unname(fit['xx']),difference=delta)}
}
cc<-do.call(rbind,check);write.csv(cc,file.path(out,'output/13_independent_weighted_QR_check_all.csv'),row.names=FALSE);stopifnot(nrow(cc)==sum(res$status=='ok'),max(abs(cc$difference))<1e-8);cat('Independent weighted-QR checks:',nrow(cc),'maximum coefficient difference',max(abs(cc$difference)),'\n')
